phase('Packages')
const unknown = WANT.filter(function (k) { return !PACKAGES[k] })
if (unknown.length) log('unknown package keys skipped: ' + unknown.join(', '))
const keys = WANT.filter(function (k) { return PACKAGES[k] })
log('base ' + BASE + ' — packages: ' + keys.join(', '))

async function run(key) {
  const p = PACKAGES[key]
  const prompt = common(key, p.title) + p.body
  const opts = { label: 'pkg:' + key, phase: 'Packages', schema: REPORT, model: 'opus', effort: p.effort, isolation: 'worktree', agentType: 'general-purpose' }
  let r = null
  try { r = await agent(prompt, opts) } catch (e) { log(key + ': first attempt failed (' + String(e && e.message).slice(0, 120) + ') — retrying once') }
  if (!r) {
    try { r = await agent(prompt, Object.assign({}, opts, { label: 'pkg:' + key + ':retry' })) } catch (e) { log(key + ': retry failed — ' + String(e && e.message).slice(0, 120)) }
  }
  log(key + (r ? ': done — ' + (r.commits ? r.commits.length : 0) + ' commit(s), ' + (r.notDone ? r.notDone.length : 0) + ' open item(s)' : ': NO RESULT'))
  return { key: key, report: r }
}

const results = await parallel(keys.map(function (k) { return function () { return run(k) } }))
return { base: BASE, results: results.filter(Boolean) }
